{"file_path":"src/parser.js","content":"import { ParseError } from './errors.js'
import { newTable, newArray, newAot, scalar } from './nodes.js'

const INT_RE = /^[+-]?\d+(_\d+)*$/
const NUM_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function isWs(ch) {
  return ch === ' ' || ch === '\t'
}

function skipWs(line, pos) {
  while (pos < line.length && isWs(line[pos])) pos++
  return pos
}

function isBareChar(ch) {
  return /[A-Za-z0-9_-]/.test(ch)
}

function parseBasicString(line, pos, lineNo) {
  // line[pos] === '"'
  pos++
  let out = ''
  while (true) {
    if (pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
    const ch = line[pos]
    if (ch === '"') {
      pos++
      return { value: out, pos }
    }
    if (ch === '\\') {
      pos++
      if (pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
      const esc = line[pos]
      if (esc === '"') { out += '"'; pos++ }
      else if (esc === '\\') { out += '\\'; pos++ }
      else if (esc === 'n') { out += '\n'; pos++ }
      else if (esc === 't') { out += '\t'; pos++ }
      else if (esc === 'r') { out += '\r'; pos++ }
      else if (esc === '0') { out += '\0'; pos++ }
      else if (esc === 'u') {
        const hex = line.slice(pos + 1, pos + 5)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          pos += 5
        } else {
          throw new ParseError(lineNo, 'invalid escape \\u')
        }
      } else {
        throw new ParseError(lineNo, `invalid escape \\${esc}`)
      }
      continue
    }
    out += ch
    pos++
  }
}

function parseLiteralString(line, pos, lineNo) {
  // line[pos] === "'"
  pos++
  let out = ''
  while (true) {
    if (pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
    const ch = line[pos]
    if (ch === "'") {
      pos++
      return { value: out, pos }
    }
    out += ch
    pos++
  }
}

function parseName(line, pos, lineNo) {
  if (pos < line.length && line[pos] === '"') {
    const { value, pos: p2 } = parseBasicString(line, pos, lineNo)
    return { value, pos: p2 }
  }
  if (pos < line.length && line[pos] === "'") {
    const { value, pos: p2 } = parseLiteralString(line, pos, lineNo)
    return { value, pos: p2 }
  }
  const start = pos
  while (pos < line.length && isBareChar(line[pos])) pos++
  if (pos === start) throw new ParseError(lineNo, 'expected a name')
  return { value: line.slice(start, pos), pos }
}

function parseDottedName(line, pos, lineNo) {
  const parts = []
  while (true) {
    pos = skipWs(line, pos)
    const { value, pos: p2 } = parseName(line, pos, lineNo)
    parts.push(value)
    pos = skipWs(line, p2)
    if (pos < line.length && line[pos] === '.') {
      pos++
      continue
    }
    break
  }
  return { parts, pos }
}

function parseBareToken(line, pos) {
  const start = pos
  while (pos < line.length) {
    const ch = line[pos]
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
    pos++
  }
  return { token: line.slice(start, pos), pos }
}

function interpretBareToken(token, lineNo) {
  if (token === 'true') return scalar('boolean', true)
  if (token === 'false') return scalar('boolean', false)
  if (INT_RE.test(token)) {
    return scalar('integer', parseInt(token.replace(/_/g, ''), 10))
  }
  if (NUM_RE.test(token)) {
    return scalar('float', parseFloat(token.replace(/_/g, '')))
  }
  throw new ParseError(lineNo, `invalid value ${token}`)
}

function checkTrailing(line, pos, lineNo, message) {
  pos = skipWs(line, pos)
  if (pos >= line.length) return
  const ch = line[pos]
  if (ch === '#' || ch === ';') return
  throw new ParseError(lineNo, message)
}

// Assign value at dotted `parts` inside `table`, with pathPrefix being the
// path (array of decoded names) leading to `table` itself.
function assignKey(table, parts, valueNode, lineNo, pathPrefix) {
  let cur = table
  const full = pathPrefix.slice()
  for (let i = 0; i < parts.length - 1; i++) {
    const name = parts[i]
    full.push(name)
    const existing = cur.map.get(name)
    if (existing === undefined) {
      const t = newTable()
      cur.map.set(name, t)
      cur = t
    } else if (existing.t === 'table') {
      cur = existing
    } else if (existing.t === 'aot') {
      cur = existing.items[existing.items.length - 1]
    } else {
      throw new ParseError(lineNo, `${full.join('.')} is not a table`)
    }
  }
  const leaf = parts[parts.length - 1]
  full.push(leaf)
  if (cur.map.has(leaf)) {
    throw new ParseError(lineNo, `key ${full.join('.')} is defined twice`)
  }
  cur.map.set(leaf, valueNode)
}

function resolveHeader(root, parts, isArrayHeader, lineNo) {
  let cur = root
  const path = []
  for (let i = 0; i < parts.length - 1; i++) {
    const name = parts[i]
    path.push(name)
    const existing = cur.map.get(name)
    if (existing === undefined) {
      const t = newTable()
      cur.map.set(name, t)
      cur = t
    } else if (existing.t === 'table') {
      cur = existing
    } else if (existing.t === 'aot') {
      cur = existing.items[existing.items.length - 1]
    } else {
      throw new ParseError(lineNo, `${path.join('.')} is not a table`)
    }
  }
  const leaf = parts[parts.length - 1]
  path.push(leaf)
  if (isArrayHeader) {
    let existing = cur.map.get(leaf)
    if (existing === undefined) {
      existing = newAot()
      cur.map.set(leaf, existing)
    } else if (existing.t !== 'aot') {
      throw new ParseError(lineNo, `${path.join('.')} is not an array of tables`)
    }
    const t = newTable()
    existing.items.push(t)
    return { table: t, path }
  } else {
    const existing = cur.map.get(leaf)
    if (existing === undefined) {
      const t = newTable()
      cur.map.set(leaf, t)
      return { table: t, path }
    } else if (existing.t === 'table') {
      if (existing.headerDefined) {
        throw new ParseError(lineNo, `table ${path.join('.')} is defined twice`)
      }
      existing.headerDefined = true
      return { table: existing, path }
    } else {
      throw new ParseError(lineNo, `${path.join('.')} is not a table`)
    }
  }
}

// path: array of decoded name strings giving the context path of the value
// being parsed (used to seed nested inline-table error paths).
function parseValue(line, pos, lineNo, path) {
  pos = skipWs(line, pos)
  if (pos >= line.length) throw new ParseError(lineNo, 'expected a value')
  const ch = line[pos]
  if (ch === ',' || ch === ']' || ch === '}' || ch === '#' || ch === ';') {
    throw new ParseError(lineNo, 'expected a value')
  }
  if (ch === '"') {
    const { value, pos: p2 } = parseBasicString(line, pos, lineNo)
    return { node: scalar('string', value), pos: p2 }
  }
  if (ch === "'") {
    const { value, pos: p2 } = parseLiteralString(line, pos, lineNo)
    return { node: scalar('string', value), pos: p2 }
  }
  if (ch === '[') {
    return parseArray(line, pos, lineNo, path)
  }
  if (ch === '{') {
    return parseInlineTable(line, pos, lineNo, path)
  }
  const { token, pos: p2 } = parseBareToken(line, pos)
  return { node: interpretBareToken(token, lineNo), pos: p2 }
}

function parseArray(line, pos, lineNo, path) {
  pos++ // consume '['
  const arr = newArray()
  pos = skipWs(line, pos)
  if (pos < line.length && line[pos] === ']') {
    pos++
    return { node: arr, pos }
  }
  while (true) {
    const { node: val, pos: p2 } = parseValue(line, pos, lineNo, path)
    arr.items.push(val)
    pos = skipWs(line, p2)
    if (pos >= line.length) throw new ParseError(lineNo, 'unterminated array')
    const ch = line[pos]
    if (ch === ']') {
      pos++
      break
    } else if (ch === ',') {
      pos++
      pos = skipWs(line, pos)
      if (pos >= line.length) throw new ParseError(lineNo, 'unterminated array')
      if (line[pos] === ']') {
        pos++
        break
      }
      continue
    } else {
      throw new ParseError(lineNo, 'unterminated array')
    }
  }
  return { node: arr, pos }
}

function parseInlineTable(line, pos, lineNo, path) {
  pos++ // consume '{'
  const table = newTable()
  pos = skipWs(line, pos)
  if (pos < line.length && line[pos] === '}') {
    pos++
    return { node: table, pos }
  }
  while (true) {
    pos = skipWs(line, pos)
    const { parts, pos: p2 } = parseDottedName(line, pos, lineNo)
    pos = skipWs(line, p2)
    if (pos >= line.length || line[pos] !== '=') {
      throw new ParseError(lineNo, 'expected = in an inline table')
    }
    pos++
    pos = skipWs(line, pos)
    const entryPath = path.concat(parts)
    const { node: val, pos: p3 } = parseValue(line, pos, lineNo, entryPath)
    assignKey(table, parts, val, lineNo, path)
    pos = skipWs(line, p3)
    if (pos >= line.length) throw new ParseError(lineNo, 'unterminated inline table')
    const ch = line[pos]
    if (ch === '}') {
      pos++
      break
    } else if (ch === ',') {
      pos++
      continue
    } else {
      throw new ParseError(lineNo, 'unterminated inline table')
    }
  }
  return { node: table, pos }
}

function handleHeaderLine(line, startPos, lineNo, root, state) {
  let pos = startPos
  pos++ // consume '['
  let isArray = false
  if (pos < line.length && line[pos] === '[') {
    isArray = true
    pos++
  }
  const { parts, pos: p2 } = parseDottedName(line, pos, lineNo)
  pos = skipWs(line, p2)
  const needed = isArray ? 2 : 1
  for (let k = 0; k < needed; k++) {
    if (pos >= line.length || line[pos] !== ']') {
      throw new ParseError(lineNo, 'unterminated table header')
    }
    pos++
  }
  pos = skipWs(line, pos)
  checkTrailing(line, pos, lineNo, 'trailing text after a table header')
  const { table, path } = resolveHeader(root, parts, isArray, lineNo)
  state.currentTable = table
  state.currentPath = path
}

function handleKeyLine(line, startPos, lineNo, root, state) {
  let pos = startPos
  const { parts, pos: p1 } = parseDottedName(line, pos, lineNo)
  pos = skipWs(line, p1)
  if (pos >= line.length || line[pos] !== '=') {
    throw new ParseError(lineNo, 'expected key = value')
  }
  pos++
  pos = skipWs(line, pos)
  const path = state.currentPath.concat(parts)
  const { node: val, pos: p2 } = parseValue(line, pos, lineNo, path)
  pos = skipWs(line, p2)
  checkTrailing(line, pos, lineNo, 'trailing text after a value')
  assignKey(state.currentTable, parts, val, lineNo, state.currentPath)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  const state = { currentTable: root, currentPath: [] }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const lineNo = i + 1
    let pos = 0
    while (pos < line.length && isWs(line[pos])) pos++
    if (pos >= line.length) continue
    const ch = line[pos]
    if (ch === '#' || ch === ';') continue
    if (ch === '[') {
      handleHeaderLine(line, pos, lineNo, root, state)
    } else {
      handleKeyLine(line, pos, lineNo, root, state)
    }
  }
  return root
}
"}

