    }
    case 'array':
    case 'aot': {
      if (node.items.length === 0) return '[]'
      const lines = node.items.map((it) => `${padIn}${jsonValue(it, indentLevel + 1)}`)
      return `[\n${lines.join(',\n')}\n${pad}]`
    }
    default:
      throw new Error(`unknown node type ${node.t}`)
  }
}

export function toJson(root) {
