}

function typeOf(node) {
  switch (node.t) {
    case 'table':
      return 'table'
    case 'array':
    case 'aot':
      return 'array'
    case 'string':
      return 'string'
    case 'integer':
      return 'integer'
    case 'float':
      return 'float'
    case 'boolean':
      return 'boolean'
    default:
      throw new Error(`unknown node type ${node.t}`)
  }
}

function collectKeys(node, path, out) {
  if (node.t === 'table') {
    const keys = [...node.map.keys()].sort()
    for (const k of keys) {
      const child = node.map.get(k)
      const childPath = path ? `${path}.${k}` : k
      out.push(`${childPath} ${typeOf(child)}`)
      collectKeys(child, childPath, out)
    }
