    node.items.forEach((it, idx) => {
      const childPath = `${path}[${idx}]`
      out.push(`${childPath} ${typeOf(it)}`)
      collectKeys(it, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  collectKeys(root, '', out)
  return out.length ? out.join('\n') + '\n' : ''
}
"}

